		<view class="content">
			<!-- 进度条：上报计划、服务协议、制定数据、贸易合同、进销项发票、银行交易、完结 -->
			<view class="progress-card">
				<view class="steps">
					<view class="step-col" v-for="(s, i) in steps" :key="i">
						<view class="node-wrap">
							<view v-if="i < steps.length - 1" class="line" :class="{ done: i < currentStep }"></view>
							<text v-if="i === currentStep" class="rocket">🚀</text>
							<view class="node" :class="nodeClass(i)">
								<text v-if="i < currentStep" class="check">✓</text>
								<text v-else class="num">{{ i + 1 }}</text>
							</view>
						</view>
						<text class="label" :class="{ active: i === currentStep }">{{ s }}</text>
					</view>
				</view>
			</view>

			<!-- 两行数据 -->
			<view class="data-card">
				<view class="data-row">
					<view class="data-item">
						<text class="data-label">销售总额</text>
						<text class="data-value" style="color:#2979ff">{{ summary.sales || '暂无数据' }}</text>
					</view>
					<view class="data-item">
						<text class="data-label">进货总额</text>
						<text class="data-value" style="color:#2ECC71">{{ summary.purchase || '暂无数据' }}</text>
					</view>
					<view class="data-item">
						<text class="data-label">利润金额</text>
						<text class="data-value" style="color:#FF6B6B">{{ summary.profit || '暂无数据' }}</text>
