						<text class="data-value" style="color:#F39C12">{{ summary.downstream || '暂无数据' }}</text>
					</view>
				</view>
			</view>

			<!-- 查看按钮：未到“贸易合同”步骤则本月贸易合同按钮置灰 -->
			<view class="action-row">
				<view class="action-btn primary" @click="onViewMonthData">查看本月数据</view>
				<view class="action-btn" :class="{ disabled: !canViewContract }" @click="onViewContract">
