<script>
	export default {
		data() {
			return {
				enterpriseList: [
					'杭州超级供应链有限公司',
					'上海贸易有限公司',
					'深圳科技股份公司'
				],
				enterpriseIndex: 0,
				currentDate: '2026-08',
				planAmount: '¥ 12,580,000.00',
				profitRate: '1‰',
				steps: ['上报计划', '服务协议', '制定数据', '贸易合同', '进销项发票', '银行交易', '完结'],
				// 默认进度：当前停在“制定数据”（索引2），尚未到达“贸易合同”（索引3），故贸易合同按钮置灰
				currentStep: 2,
				summary: {
					sales: '¥ 8,200,000.00',
					purchase: '¥ 7,380,000.00',
					profit: '¥ 8,200.00',
					upstream: '',
					downstream: ''
				},
				historyList: [
					{ month: '2026年07月' },
					{ month: '2026年06月' },
					{ month: '2026年05月' }
				],
				guideBg: 'linear-gradient(120deg, #FF5F6D 0%, #FF8E53 65%, #FFC371 100%)'
			}
		},
		computed: {
			dateLabel() {
				if (!this.currentDate) return '选择月份'
				const [y, m] = this.currentDate.split('-')
				return `${y}年${m}月`
			},
			// “贸易合同”为第 4 步（索引 3），进度未达到则禁用查看
			canViewContract() {
				return this.currentStep >= 3
			}
		},
		onShareAppMessage() {
			return {
				title: '我的企业 - 超级供应链',
				path: '/pages/tabBar/enterprise/enterprise'
			}
		},
		methods: {
			nodeClass(i) {
				if (i < this.currentStep) return 'done'
				if (i === this.currentStep) return 'active'
				return 'todo'
			},
			// 跳转到统一的数据详情页（page/enterprise/data）
			// 参数: menu=plan|actual|contract|bank|agreement, month=YYYY-MM, enterprise=index
			goDataPage({ menu = 'actual', month = null, enterprise = null }) {
				const query = []
				query.push('menu=' + encodeURIComponent(menu))
				if (month) query.push('month=' + encodeURIComponent(month))
				if (enterprise !== null) query.push('enterprise=' + String(enterprise))
				uni.navigateTo({ url: '/pages/enterprise/data?' + query.join('&') })
			},
			onEnterpriseChange(e) {
				this.enterpriseIndex = e.detail.value
			},
			onDateChange(e) {
				this.currentDate = e.detail.value
			},
			onViewMonthData() {
				this.goDataPage({ menu: 'actual', month: this.currentDate, enterprise: this.enterpriseIndex })
			},
			onViewContract() {
				if (!this.canViewContract) {
					uni.showToast({ title: '进度未到“贸易合同”步骤', icon: 'none' })
					return
				}
				this.goDataPage({ menu: 'contract', month: this.currentDate, enterprise: this.enterpriseIndex })
			},
			onGuide() {
				uni.showToast({ title: '打开操作须知', icon: 'none' })
			},
			onViewAll() {
				this.goDataPage({ menu: 'actual', month: null, enterprise: this.enterpriseIndex })
			},
			onHistory(h) {
				// h.month => "2026年07月" -> "2026-07"
				const m = (h.month || '').match(/(\d{4})年(\d{1,2})月/)
				const ym = m ? `${m[1]}-${m[2].padStart(2, '0')}` : null
				this.goDataPage({ menu: 'actual', month: ym, enterprise: this.enterpriseIndex })
			},
			goMyEnterprise() {
				uni.switchTab({ url: '/pages/tabBar/enterprise/enterprise' })
			},
			goBank() {
				this.goDataPage({ menu: 'bank', month: this.currentDate, enterprise: this.enterpriseIndex })
			},
			goAllContract() {
				this.goDataPage({ menu: 'contract', month: this.currentDate, enterprise: this.enterpriseIndex })
			}
		}
	}
</script>

